import{_ as h}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as p,D as r,o as d,c as k,I as o,w as u,k as s,a as g,R as i,b as m,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const R=JSON.parse('{"title":"存储、复制与可靠性","description":"分区日志、segment、复制、ISR、水位和数据丢失边界，理解 Kafka 如何持久化消息并保证可靠性。","frontmatter":{"title":"存储、复制与可靠性","date":"2026-11-05T00:00:00.000Z","category":"Java课程","tags":["Java","Kafka","ISR"],"description":"分区日志、segment、复制、ISR、水位和数据丢失边界，理解 Kafka 如何持久化消息并保证可靠性。"},"headers":[],"relativePath":"courses/java/16-Kafka/08-存储复制与可靠性.md","filePath":"courses/java/16-Kafka/08-存储复制与可靠性.md","lastUpdated":1793885095000}'),b={name:"courses/java/16-Kafka/08-存储复制与可靠性.md"},A=s("h1",{id:"存储、复制与可靠性",tabindex:"-1"},[g("存储、复制与可靠性 "),s("a",{class:"header-anchor",href:"#存储、复制与可靠性","aria-label":'Permalink to "存储、复制与可靠性"'},"​")],-1),_=i(`<h2 id="分区日志与-segment" tabindex="-1">分区日志与 segment <a class="header-anchor" href="#分区日志与-segment" aria-label="Permalink to &quot;分区日志与 segment&quot;">​</a></h2><p>每个分区是一个<strong>有序的、不可变的追加日志</strong>。消息只能追加到末尾，不能修改已有消息。物理上，每个分区日志按 <strong>segment</strong>（段文件）切分存储。</p><p>可以把分区想成一个编号连续的账本：</p><ul><li><strong>Producer</strong> 在账本末尾写新条目（追加）</li><li><strong>Consumer</strong> 自己保存&quot;读到了第几条&quot;的书签（offset）</li><li><strong>segment</strong> 是账本的分卷，便于索引和清理</li></ul><p>当前活跃的 segment 叫 active segment，Producer 写入的目标就是它。当 active segment 达到配置大小（默认 1GB）或时间阈值时，滚动成新 segment。旧的 segment 变为只读。</p><h3 id="消息不会因消费而删除" tabindex="-1">消息不会因消费而删除 <a class="header-anchor" href="#消息不会因消费而删除" aria-label="Permalink to &quot;消息不会因消费而删除&quot;">​</a></h3><p>这是 Kafka 和传统消息队列的关键区别。传统队列中消费者取走消息后，消息就从队列中消失；Kafka 的消息不管被多少消费者读取过，都留在分区日志中，直到被清理。</p><p>清理策略有两种：</p><table><thead><tr><th>策略</th><th>行为</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>按时间删除（delete）</strong></td><td>超过 <code>retention.ms</code>（默认 7 天）的 segment 被整体删除</td><td>事件流、日志</td></tr><tr><td><strong>紧凑化（compact）</strong></td><td>对每个 key 只保留最新的 value，旧 value 被清理</td><td>状态快照、配置变更</td></tr></tbody></table><p>两种不能混为一谈。紧凑化不是删除旧 segment，而是对同一 key 的多条消息只留最新一条。比如 Topic 中有 <code>user-1</code> 的多条消息（改名、改名、改名），紧凑化后只剩最后一条改名结果。</p><h2 id="leader、follower-与-isr" tabindex="-1">Leader、Follower 与 ISR <a class="header-anchor" href="#leader、follower-与-isr" aria-label="Permalink to &quot;Leader、Follower 与 ISR&quot;">​</a></h2><p>单节点 Broker 没有冗余——磁盘损坏消息全丢。生产环境需要**副本（replica）**保证数据安全。</p><p>每个分区有一个 Leader 和零到多个 Follower：</p><ul><li><strong>Leader</strong>：接收该分区所有读写请求。Producer 写消息到 Leader，Consumer 从 Leader 读消息。</li><li><strong>Follower</strong>：从 Leader 拉取数据复制到自己。Follower 不直接服务客户端读写。</li><li><strong>ISR（In-Sync Replicas）</strong>：当前满足同步条件的副本集合，包括 Leader 和跟得上进度的 Follower。</li></ul><h3 id="副本怎么工作" tabindex="-1">副本怎么工作 <a class="header-anchor" href="#副本怎么工作" aria-label="Permalink to &quot;副本怎么工作&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span>Producer 写消息 → Leader 追加到日志</span></span>
<span class="line"><span>                  ↓</span></span>
<span class="line"><span>              Follower 1 拉取复制 ✓（在 ISR 中）</span></span>
<span class="line"><span>              Follower 2 拉取复制 ✓（在 ISR 中）</span></span>
<span class="line"><span>              Follower 3 落后太多 ✗（不在 ISR 中）</span></span></code></pre></div><p>Follower 通过持续拉取 Leader 的最新消息来保持同步。如果某个 Follower 落后太多（超过 <code>replica.lag.time.max.ms</code>，默认 30 秒），它会被移出 ISR。ISR 是动态变化的——Follower 赶上来会重新加入 ISR。</p><h3 id="acks-all-真的可靠吗" tabindex="-1"><code>acks=all</code> 真的可靠吗 <a class="header-anchor" href="#acks-all-真的可靠吗" aria-label="Permalink to &quot;\`acks=all\` 真的可靠吗&quot;">​</a></h3><p><code>acks=all</code> 的含义是&quot;等待当前 ISR 中所有副本确认后才向 Producer 返回成功&quot;。但要注意：</p><ul><li>单节点实验只有一个副本，ISR 只有 Leader 自己，<code>acks=all</code> 等于 <code>acks=1</code>，不能验证多副本容错。</li><li>如果 <code>min.insync.replicas=1</code>，即使有 3 个副本，只要 1 个在 ISR 中就可以确认写入——这意味着可能只写入了一个副本。</li></ul><p><strong>举例</strong>：副本数 3、<code>min.insync.replicas=2</code>、Producer <code>acks=all</code>：</p><ol><li><strong>三副本健康</strong>：ISR = {Leader, F1, F2}，写入需等至少 2 个确认 → 成功</li><li><strong>F2 离开 ISR</strong>：ISR = {Leader, F1}，仍有 2 个同步副本 ≥ <code>min.insync.replicas=2</code> → 继续可写</li><li><strong>只剩 Leader 同步</strong>：ISR = {Leader}，1 &lt; <code>min.insync.replicas=2</code> → 拒绝写入，Producer 收到异常</li></ol><p>第 3 种情况看起来是&quot;不可用&quot;，但它是保护数据一致性的正确行为：宁可拒绝写入，也不能让消息只存在一个副本上。如果此时把 <code>min.insync.replicas</code> 设成 1 来&quot;恢复可用性&quot;，就回到了只有一个副本保证的状态——后续 Leader 磁盘损坏，这条消息就永久丢失了。</p><p><strong>结论</strong>：不能单看 <code>acks=all</code> 就宣称多副本安全。副本数、<code>min.insync.replicas</code> 和 ISR 状态三个配置一起看，才知道实际保障。<a href="https://kafka.apache.org/41/configuration/producer-configs/" target="_blank" rel="noreferrer">Producer ACK 配置</a>。</p>`,24),y=i('<h2 id="hw、leo-与可见性" tabindex="-1">HW、LEO 与可见性 <a class="header-anchor" href="#hw、leo-与可见性" aria-label="Permalink to &quot;HW、LEO 与可见性&quot;">​</a></h2><p>这两个概念描述了分区日志中消息的&quot;可见性边界&quot;。</p><h3 id="leo-log-end-offset" tabindex="-1">LEO（Log End Offset） <a class="header-anchor" href="#leo-log-end-offset" aria-label="Permalink to &quot;LEO（Log End Offset）&quot;">​</a></h3><p>日志末端位置——下一条要写入的 offset。如果分区当前有 offset 0~4 的五条消息，LEO 是 5。</p><h3 id="hw-high-watermark" tabindex="-1">HW（High Watermark） <a class="header-anchor" href="#hw-high-watermark" aria-label="Permalink to &quot;HW（High Watermark）&quot;">​</a></h3><p>已满足复制可见性条件的 offset——Consumer 能读到的最大 offset。HW ≤ LEO。</p><p><strong>为什么需要 HW？</strong> 如果 Leader 写了一条消息但 Follower 还没复制，此时 Leader 故障，消息会丢失。为了防止 Consumer 读到这种&quot;未完全复制的消息&quot;，Kafka 规定 Consumer 只能读到 HW 以下的消息。</p><h3 id="三个不同的-成功" tabindex="-1">三个不同的&quot;成功&quot; <a class="header-anchor" href="#三个不同的-成功" aria-label="Permalink to &quot;三个不同的&quot;成功&quot;&quot;">​</a></h3><table><thead><tr><th>事件</th><th>含义</th><th>谁关心</th></tr></thead><tbody><tr><td>Producer 收到 ACK</td><td>Broker 已持久化消息（满足 acks 策略）</td><td>Producer</td></tr><tr><td>Consumer 能读到（HW 以上）</td><td>消息已复制到足够副本，对 Consumer 可见</td><td>Consumer</td></tr><tr><td>业务处理成功</td><td>消费者处理完消息并产生业务效果</td><td>业务方</td></tr></tbody></table><p>这三个事件不是同一件事。Producer 收到 ACK 只说明消息到了 Broker；Consumer 读到只说明能取数据；业务处理成功才是最终目标。</p><h3 id="副本故障时检查什么" tabindex="-1">副本故障时检查什么 <a class="header-anchor" href="#副本故障时检查什么" aria-label="Permalink to &quot;副本故障时检查什么&quot;">​</a></h3><p>当 Broker 故障时，分区可能需要切换 Leader。检查顺序：</p><ol><li><strong>ISR 是否有足够副本</strong>：ISR 中是否有满足 <code>min.insync.replicas</code> 的副本可做新 Leader。</li><li><strong>是否允许非 ISR 副本选主</strong>：<code>unclean.leader.election.enable</code> 如果为 <code>true</code>，允许落后副本当 Leader（可能丢数据）；如果为 <code>false</code>，ISR 不足时分区不可用（等待原 Leader 恢复）。</li></ol><p>生产环境通常设为 <code>false</code>——宁可暂时不可用也不要丢数据。但这意味着 ISR 不足时分区会停止写入，需要监控告警及时处理。</p><h2 id="消息丢失的风险点" tabindex="-1">消息丢失的风险点 <a class="header-anchor" href="#消息丢失的风险点" aria-label="Permalink to &quot;消息丢失的风险点&quot;">​</a></h2><p>整条链路上消息可能丢失的环节：</p><table><thead><tr><th>环节</th><th>丢失原因</th><th>防范</th></tr></thead><tbody><tr><td>Producer → Broker</td><td>网络断开，Producer 未重试</td><td><code>acks=all</code> + <code>retries</code> 足够大 + <code>enable.idempotence=true</code></td></tr><tr><td>Broker 单副本</td><td>磁盘损坏</td><td>副本数 ≥ 3 + <code>min.insync.replicas ≥ 2</code></td></tr><tr><td>Broker 消息保留过期</td><td>消费者长时间不消费</td><td>合理设置 <code>retention.ms</code> 或增加消费能力</td></tr><tr><td>Consumer 先提交后处理</td><td>崩溃后消息被跳过</td><td>先处理再提交 + 业务幂等</td></tr><tr><td>非干净 Leader 选举</td><td>选了落后副本当 Leader</td><td><code>unclean.leader.election.enable=false</code></td></tr></tbody></table><h2 id="最小检查" tabindex="-1">最小检查 <a class="header-anchor" href="#最小检查" aria-label="Permalink to &quot;最小检查&quot;">​</a></h2><p>用下面的命令查看实验 Topic 的分区和副本状态：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">docker exec kafka</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">lab </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">opt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">kafka</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">bin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">kafka</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">topics.sh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">bootstrap</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">server localhost:</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">9092</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">describe </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">topic learning.events</span></span></code></pre></div><p>观察每个分区的 <code>Leader</code>、<code>Replicas</code>、<code>Isr</code> 三个字段。单节点实验中三者都是同一个 Broker 编号。</p><p>如果有多节点集群，可以模拟故障：停掉 Leader 所在 Broker，观察 Topic describe 输出中 Leader 是否切换、ISR 是否缩减。<strong>实验时先记下副本数与 ISR，再模拟故障；不要在生产集群随意停节点</strong>。<a href="https://kafka.apache.org/documentation/#replication" target="_blank" rel="noreferrer">Kafka 设计与复制</a>。</p><h2 id="可靠性配置速查" tabindex="-1">可靠性配置速查 <a class="header-anchor" href="#可靠性配置速查" aria-label="Permalink to &quot;可靠性配置速查&quot;">​</a></h2><table><thead><tr><th>配置项</th><th>位置</th><th>推荐值</th><th>说明</th></tr></thead><tbody><tr><td><code>acks</code></td><td>Producer</td><td><code>all</code></td><td>等待 ISR 所有副本确认</td></tr><tr><td><code>enable.idempotence</code></td><td>Producer</td><td><code>true</code></td><td>生产者重试不产生重复</td></tr><tr><td><code>retries</code></td><td>Producer</td><td><code>Integer.MAX_VALUE</code></td><td>持续重试直到成功或超时</td></tr><tr><td><code>max.in.flight.requests.per.connection</code></td><td>Producer</td><td>≤ 5</td><td>幂等模式下的限制</td></tr><tr><td><code>replication.factor</code></td><td>Topic</td><td>≥ 3</td><td>每个分区至少 3 个副本</td></tr><tr><td><code>min.insync.replicas</code></td><td>Topic/Broker</td><td>≥ 2</td><td>至少 2 个同步副本才允许写入</td></tr><tr><td><code>unclean.leader.election.enable</code></td><td>Broker</td><td><code>false</code></td><td>不允许落后副本当 Leader</td></tr><tr><td><code>enable.auto.commit</code></td><td>Consumer</td><td><code>false</code></td><td>手动提交，处理完再提交</td></tr><tr><td><code>retention.ms</code></td><td>Topic</td><td>按需设置</td><td>消息保留时间，默认 7 天</td></tr></tbody></table>',24);function B(e,E,C,q,L,I){const n=h,l=r("ClientOnly"),c=r("Mermaid");return d(),k("div",null,[A,o(l,null,{default:u(()=>{var t,a;return[(((t=e.$frontmatter)==null?void 0:t.aside)??!0)&&(((a=e.$frontmatter)==null?void 0:a.showArticleMetadata)??!0)?(d(),m(n,{key:0,article:e.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),_,o(c,{id:"mermaid_64a56f76",graph:"flowchart%20LR%0A%20%20%20%20P%5BProducer%5D%20--%3E%20L%5BLeader%20%E6%97%A5%E5%BF%97%5D%0A%20%20%20%20L%20--%3E%20F1%5BFollower%201%5D%0A%20%20%20%20L%20--%3E%20F2%5BFollower%202%5D%0A%20%20%20%20F1%20--%3E%20I%5BISR%20%E6%BB%A1%E8%B6%B3%E7%A1%AE%E8%AE%A4%E6%9D%A1%E4%BB%B6%5D%0A%20%20%20%20F2%20--%3E%20I%0A%20%20%20%20I%20--%3E%20A%5BProducer%20%E6%94%B6%E5%88%B0%20ACK%5D%0A%20%20%20%20A%20--%3E%20C%5BConsumer%20%E5%90%8E%E7%BB%AD%E8%AF%BB%E5%8F%96%5D"}),y])}const D=p(b,[["render",B]]);export{R as __pageData,D as default};
